export default async function step(
  { requestId, recipient, fileIds, acknowledge, resolution, confirmedId },
  ctx,
) {
  if (
    !requestId ||
    !recipient ||
    !Array.isArray(fileIds) ||
    fileIds.length < 1 ||
    fileIds.length > 2 ||
    fileIds.some((x) => typeof x !== "string" || !x)
  )
    throw Error("Expected request ID, recipient and one or two file IDs");
  const key = "knowledge-ingestion:" + requestId,
    identity = JSON.stringify({ recipient, fileIds });
  let s = await ctx.state.get(key);
  if (!s)
    s = { identity, index: 0, phase: "create-ready", texts: [], polls: 0, kind: 0, offset: 0 };
  if (s.identity !== identity) throw Error("Restore original submission");
  if (s.phase.endsWith("-pending")) {
    if (acknowledge !== key || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect pending " + s.phase + " " + key);
    const p = s.phase.slice(0, -8);
    if (resolution === "absent") s.phase = (p === "index" ? "embed" : p) + "-ready";
    else if (p === "create") {
      if (!confirmedId) throw Error("Enter confirmed parse job ID");
      s.jobId = confirmedId;
      s.phase = "poll-ready";
    } else if (p === "index") {
      s.offset += s.chunk.length;
      if (s.offset >= s.current.length) {
        s.kind++;
        s.offset = 0;
      }
      s.phase = s.kind < 2 ? "embed-ready" : "done";
    } else s.phase = "done";
    await ctx.state.set(key, s);
  }
  let action = s.phase.endsWith("-ready")
    ? s.phase.slice(0, -6)
    : s.phase === "done"
      ? "done"
      : s.phase;
  if (action === "create") {
    s.phase = "create-pending";
    await ctx.state.set(key, s);
  }
  let current = s.kind === 0 ? s.translated : s.report;
  let chunk = typeof current === "string" ? current.slice(s.offset, s.offset + 3000) : "";
  return {
    key,
    action,
    fileId: fileIds[s.index] ?? "none",
    jobId: s.jobId ?? "none",
    recipient,
    combined: s.texts.join("\n\n---\n\n"),
    translated: s.translated ?? "",
    report: s.report ?? "",
    requestId,
    chunk,
    kind: s.kind,
    offset: s.offset,
  };
}

