export default async function confirm({ key, phase, status, body, messageId }, ctx) {
  const s = await ctx.state.get(key);
  if (!s) throw Error("Missing state");
  if (phase === "create") {
    if (s.phase !== "create-pending" || status < 200 || status >= 300 || !body?.id)
      throw Error("Inspect parse creation");
    s.jobId = String(body.id);
    s.phase = "poll-ready";
    s.polls = 0;
  } else if (phase === "poll") {
    if (s.phase !== "poll-ready" || status < 200 || status >= 300 || body?.job?.id !== s.jobId)
      throw Error("Invalid parse result");
    if (["FAILED", "CANCELLED"].includes(body.job.status)) throw Error("Parse failed");
    if (body.job.status === "COMPLETED") {
      if (
        !Array.isArray(body.markdown?.pages) ||
        !body.markdown.pages.length ||
        body.markdown.pages.some((p) => !p.success || typeof p.markdown !== "string")
      )
        throw Error("Incomplete parsed pages");
      s.texts.push(body.markdown.pages.map((p) => p.markdown).join("\n\n"));
      s.index++;
      s.phase =
        s.index < JSON.parse(s.identity).fileIds.length ? "create-ready" : "translate-ready";
      delete s.jobId;
    } else if (["PENDING", "RUNNING"].includes(body.job.status)) {
      if (++s.polls > 120) throw Error("Parse timeout");
      s.phase = "poll-ready";
    } else throw Error("Unexpected parse status");
  } else if (phase === "email") {
    if (s.phase !== "email-pending" || !messageId) throw Error("Inspect Gmail");
    s.phase = "done";
  }
  await ctx.state.set(key, s);
  return { ok: true };
}

