export default async function model({ key, phase, text, raw }, ctx) {
  const s = await ctx.state.get(key);
  if (
    s?.phase !== phase + "-ready" ||
    typeof text !== "string" ||
    !text.trim() ||
    raw?.candidates?.[0]?.finishReason !== "STOP"
  )
    throw Error("Incomplete model response");
  if (phase === "translate") {
    s.translated = text;
    s.phase = "analyze-ready";
  } else if (phase === "analyze") {
    s.report = text;
    s.phase = "embed-ready";
  } else throw Error("Invalid phase");
  await ctx.state.set(key, s);
  return { ok: true };
}

