export default async function vector({ key, requestId, kind, offset, chunk, embedding }, ctx) {
  const s = await ctx.state.get(key);
  if (
    s?.phase !== "embed-ready" ||
    s.kind !== kind ||
    s.offset !== offset ||
    !chunk ||
    typeof embedding !== "object"
  )
    throw Error("Unexpected embedding");
  let values = embedding.data?.[0]?.embedding;
  if (
    !Array.isArray(values) ||
    values.length !== 1024 ||
    values.some((x) => typeof x !== "number" || !Number.isFinite(x))
  )
    throw Error("Invalid Mistral embedding");
  s.phase = "index-pending";
  s.chunk = chunk;
  s.current = kind === 0 ? s.translated : s.report;
  await ctx.state.set(key, s);
  return {
    vectors: [
      {
        id: requestId + "-" + kind + "-" + offset,
        values,
        metadata: { text: chunk, kind: kind === 0 ? "translation" : "analysis", requestId },
      },
    ],
  };
}

