export default async function confirm({ key, count }, ctx) {
  const s = await ctx.state.get(key);
  if (s?.phase !== "index-pending" || count !== 1) throw Error("Inspect Pinecone upsert");
  s.offset += s.chunk.length;
  if (s.offset >= s.current.length) {
    s.kind++;
    s.offset = 0;
  }
  s.phase = s.kind < 2 ? "embed-ready" : "done";
  delete s.chunk;
  delete s.current;
  await ctx.state.set(key, s);
  return { ok: true };
}
